#include "editorcontext.h"
#include "routefiles.h"
#include "routeeditor.h"
#include "trafficroute.h"
#include <cstdio>
int main(){int total=0,failed=0;auto check=[&](bool good,const char* name){++total;if(!good){++failed;std::printf("FAIL %s\n",name);}};auto near=[](double a,double b){return std::fabs(a-b)<1e-7;};
    editorcontext::State ui;check(ui.Panel(),"browse starts visible");ui.Select("route/lane");check(!ui.Panel()&&ui.surface==editorcontext::Surface::Edit,"selection tucks browser");ui.Open(editorcontext::Popup::Vehicles);ui.Open(editorcontext::Popup::Movement);check(ui.popup==editorcontext::Popup::Movement,"one property popup replaces previous");ui.Back();check(ui.surface==editorcontext::Surface::Edit&&ui.popup==editorcontext::Popup::None,"back keeps selection");ui.Advanced();check(ui.Panel(),"advanced retains complete editor surface");ui.Back();ui.pinned=true;check(ui.Panel(),"optional pin preserves browser");ui.Browse();check(ui.selection=="route/lane","browsing preserves object identity");
    for(auto size:std::vector<std::pair<double,double>>{{1280,720},{1366,768},{1600,900},{1920,1080},{2560,1440},{3440,1440}}){const auto r=editorcontext::Clamp({size.first-20,size.second-5,380,340},size.first,size.second-190);check(r.x>=12&&r.y>=12&&r.x+r.w<=size.first-12&&r.y+r.h<=size.second-202,"popup remains inside usable screen");check(r.Contains(r.x+5,r.y+5)&&!r.Contains(r.x-1,r.y),"drawn and hit rectangle agree");}
    double value;for(auto text:{"NaN","inf","1oops","","--5"})check(!editorcontext::Number(text,value),"reject malformed exact input");check(editorcontext::Number("-123.125",value)&&near(value,-123.125),"signed decimal exact input");
    trafficdata::Route r;r.name="ed_transform";r.world="#world";r.ring=false;r.closed=false;r.lanes=2;r.width=12;r.points={{0,0,0},{0,100,0},{0,200,0},{0,300,0}};r.lanePlan.enabled=true;r.lanePlan.base.forward=r.lanePlan.base.reverse=1;laneplan::EnsureSections(r.lanePlan,4);const auto before=trafficroute::Build(r);const auto ids=r.lanePlan.sectionIds;
    auto& t=lanetransform::Edit(r.lanePlan.transforms,0,-1,{0,0,0});lanetransform::Translate(t,{7,11,13});const auto transformed=trafficroute::Build(r);check(!transformed.error&&near(transformed.lane[0][0].x,before.lane[0][0].x+7)&&near(transformed.lane[0][0].z,13),"compiled lane moves in XYZ");check(near(transformed.lane[1][0].x,before.lane[1][0].x)&&r.points[0].x==0&&ids==r.lanePlan.sectionIds,"opposite lane spine and identities unchanged");check(trafficroute::Spatial(transformed)&&transformed.basis[0].right.size()==std::size_t(transformed.Count()),"transformed geometry publishes matching frames");
    const auto record=lanetransform::Write(r.lanePlan.transforms);check(lanetransform::Write(lanetransform::Read(record))==record,"exact transform persistence");auto snapshot=r;r.lanePlan.transforms.records[0].shift.x+=9;check(lanetransform::Write(snapshot.lanePlan.transforms)==record,"immutable saved copy survives working edits");r=snapshot;
    routefiles::File file;file.worldId="world";routefiles::Route stored;stored.id=r.name;stored.world=r.world;stored.closed=false;stored.points=r.points;stored.lanePlan=r.lanePlan;file.routes.push_back(stored);const auto text=routefiles::Format(file);routefiles::File parsed;std::vector<std::string> problems;check(routefiles::Parse(text,"fixture.ini",parsed,problems)&&lanetransform::Write(parsed.routes[0].lanePlan.transforms)==record,"editor snapshot round trip retains transforms");trafficdata::Data data;trafficdata::Read(text,"fixture.ini",data);check(data.routes.size()==1&&lanetransform::Write(data.routes[0].lanePlan.transforms)==record,"runtime consumes same transformed route");
    const auto original=trafficroute::Build(r);auto moved=routeeditor::Translated(r,31,-9,4);const auto translated=trafficroute::Build(moved);check(near(translated.lane[0][0].x,original.lane[0][0].x+31)&&near(translated.lane[0][0].z,original.lane[0][0].z+4),"parent anchoring moves lane exactly once");const auto centre=routeeditor::Centre(r);const auto rotated=trafficroute::Build(routeeditor::Turned(r,.7));const auto expected=lanetransform::Apply(lanetransform::Rotation(2,.7),{original.lane[0][0].x-centre.x,original.lane[0][0].y-centre.y,original.lane[0][0].z-centre.z});check(near(rotated.lane[0][0].x,centre.x+expected.x)&&near(rotated.lane[0][0].y,centre.y+expected.y),"parent rotation conjugates independent transform");
    routeeditor::Draft draft(r);auto edited=r;lanetransform::Translate(edited.lanePlan.transforms.records[0],{1,2,3});draft.Edit(edited);draft.Undo();check(lanetransform::Write(draft.Value().lanePlan.transforms)==record,"undo restores lane transform exactly");draft.Redo();check(lanetransform::Write(draft.Value().lanePlan.transforms)!=record,"redo restores lane edit");
    auto section=r;section.lanePlan.transforms={};for(int index:{0,1}){auto& a=lanetransform::Edit(section.lanePlan.transforms,0,index,{0,0,0});a.shift={10,0,0};}const auto contiguous=trafficroute::Build(section);for(double source:{.95,1.0,1.05,1.9}){const int i=int(contiguous.ToLine(source));check(near(contiguous.lane[0][i].x,before.lane[0][i].x+10),"adjacent section union never double applies translation");}const int far=int(contiguous.ToLine(2.9));check(near(contiguous.lane[0][far].x,before.lane[0][far].x),"unselected distant stretch remains untouched");
    auto plan=section.lanePlan;laneplan::Insert(plan,1);check(plan.transforms.records[1].section==2,"insert preserves transform section scope");laneplan::Remove(plan,1);check(plan.transforms.records[1].section==1,"remove repairs transform scope");const auto cut=laneplan::Remap(plan,{1,2});check(cut.transforms.records.size()==1&&cut.transforms.records[0].section==0,"cut retains matching transform");
    auto rotatedLane=r;lanetransform::Compose(rotatedLane.lanePlan.transforms.records[0],lanetransform::Rotation(0,.35),{0,0,0});const auto pitched=trafficroute::Build(rotatedLane);check(!pitched.error&&pitched.lane[0].back().z>80,"lane pitch reaches compiled traffic samples");
    auto invalid=r;invalid.lanePlan.transforms.records[0].matrix={};check(trafficroute::Build(invalid).error!=nullptr,"singular geometry refused before runtime");const auto future=lanetransform::Read("9 unrecognized future transform");check(lanetransform::Write(future)=="9 unrecognized future transform","unknown metadata retained verbatim");check(lanetransform::Read("1 999999999").unsupported.size()>0,"unbounded record count refused");
    r.lanePlan.transforms={};const auto legacy=trafficroute::Build(r);check(legacy.Count()==before.Count()&&near(legacy.lane[0][0].x,before.lane[0][0].x),"empty additive metadata preserves old geometry");
    std::vector<trafficdata::Vec> corner{{0,0,0},{100,0,0},{100,100,0}};check(near(routecurve::CornerLimit(corner,1,false),45),"sharp turn reports true adjoining-section radius limit");check(routecurve::CornerLimit(corner,0,false)==0,"open end is not an invented junction bend");const auto sharp=routecurve::Build(corner,{},false),rounded=routecurve::Build(corner,{0,20,0},false);check(sharp.points.size()==3&&rounded.points.size()>3,"selected corner can remain sharp or become rounded");check(near(rounded.points.front().x,0)&&near(rounded.points.back().y,100),"bend editing preserves adjoining endpoint positions");
    std::printf("contextual_editor: %d checks, %d failures\n",total,failed);return failed?1:0;
}
